<script lang="ts">
 import {enhance} from '$app/forms';
 import {money,type FinanceWorkspace,type FinanceAnalysis} from '$lib/finance';
 import type {ConstructionWorkspace} from '$lib/construction-finance';
 let {data,form}:{data:{workspace:FinanceWorkspace;construction:ConstructionWorkspace;payments?:{version:string;configured:boolean;intents:{id:string;openItemId:string;amount:number;status:string;url?:string;error?:string}[];receipts:{eventId:string;status:string;error?:string}[]};basePath:string};form?:{message?:string;failed?:boolean;analysis?:FinanceAnalysis}|null}=$props();
 const c=$derived(data.construction),s=$derived(c.state),w=$derived(data.workspace);
 let selected=$state(''),trade=$state('');const visible=$derived(c.jobs.filter(j=>(!selected||j.jobId===selected)&&(!trade||c.tradeByJob?.[j.jobId]===trade)));
 const jobName=(id:string)=>w.jobChoices.find(j=>j.id===id)?.name||id;
 const percent=(n:number|null)=>n===null?'Unknown':`${(n*100).toFixed(1)}%`;
</script>
<svelte:head><title>Construction finance · TurnKeyOps</title></svelte:head>
<div class="construction">
 <header><div><p class="eyebrow">FINANCE · CONSTRUCTION</p><h1>Bill progress. Review the finish.</h1><p>Contracts, earned revenue and retained balances from authoritative financial records.</p></div><a href={`${data.basePath}/finance`}>Accounting workspace</a>{#if c.canControl}<a href={`${data.basePath}/finance/operations`}>Labor, accruals & close operations</a>{/if}</header>
 {#if form?.message}<p role={form.failed?'alert':'status'} class="feedback">{form.message}</p>{/if}
 <nav aria-label="Construction report exports">{#each [['health','Job health'],['codes','Cost codes'],['categories','Categories'],['billing','Billing'],['retainage','Retainage']] as [kind,label]}<a href={`${data.basePath}/finance/construction/export?type=${kind}&job=${encodeURIComponent(selected)}&trade=${encodeURIComponent(trade)}`}>Export {label} CSV</a>{/each}</nav>
 <nav aria-label="Construction finance sections"><a href="#health">Job health</a><a href="#billing">Progress billing</a><a href="#retainage">Retainage</a><a href="#wip">WIP & close</a><a href="#setup">Setup & forecasts</a></nav>
 {#if form?.analysis}<section aria-label="Bob construction review"><h2>{form.analysis.title}</h2><p>{form.analysis.summary}</p>{#each form.analysis.findings as finding}<article><p>{finding.severity} · {finding.message}</p><p>{finding.suggestedAction}</p>{#each finding.sourceIds as source}<p>Source: {source}</p>{/each}</article>{/each}{#each form.analysis.limitations as note}<p>{note}</p>{/each}</section>{/if}
 <section><h2>Bob construction review</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="action" value="bob"/><label>Review<select name="tool"><option value="finance.construction-health">Projected cost and margin</option><option value="finance.construction-wip">Under / overbilling</option><option value="finance.construction-retainage">Retainage balances</option><option value="finance.construction-backlog">Backlog definitions</option>{#if c.canControl}<option value="finance.time-blockers">Time and close blockers</option><option value="finance.vendor-compliance">Expired vendor insurance</option>{/if}</select></label><label>As of<input name="asOf" type="date" required/></label><button>Review source-backed construction finances</button></form></section>
 <section id="health"><div class="heading"><h2>Job financial health</h2><label>Filter by Job<select bind:value={selected}><option value="">All construction Jobs</option>{#each s.contracts as contract}<option value={contract.jobId}>{jobName(contract.jobId)}</option>{/each}</select></label><label>Trade<select bind:value={trade}><option value="">All trades</option>{#each [...new Set(Object.values(c.tradeByJob??{}))] as name}<option value={name}>{name}</option>{/each}</select></label><button type="button" onclick={()=>window.print()}>Print reports</button></div>
 <p>Remaining commitments are relieved by posted costs. Earned revenue is calculated separately from billing. Unknown forecasts remain exceptions.</p>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable financial tables need keyboard focus.) -->
 <div class="table-scroll" role="region" aria-label="Job financial health table" tabindex="0"><table><caption>Current construction financial position</caption><thead><tr><th scope="col">Job</th><th scope="col">Contract</th><th scope="col">Actual</th><th scope="col">Remaining commitment</th><th scope="col">Forecast remaining</th><th scope="col">EAC</th><th scope="col">Projected profit / margin</th><th scope="col">Exceptions</th></tr></thead><tbody>{#each visible as j}<tr><th scope="row"><a href={`${data.basePath}/jobs/${j.jobId}`}>{jobName(j.jobId)}</a></th><td>{money(j.contractValue)}</td><td>{money(j.actualCost)}</td><td>{money(j.remainingCommitment)}</td><td>{money(j.remainingForecast)}</td><td>{money(j.estimatedFinalCost)}</td><td>{money(j.projectedProfit)} / {percent(j.projectedMargin)}</td><td>{#each j.exceptions as exception}<p>{exception}</p>{:else}Ready for review{/each}</td></tr>{:else}<tr><td colspan="8">No construction contracts configured. Set up a contract and reviewed forecast below.</td></tr>{/each}</tbody></table></div>
 </section>
 <section><h2>Cost categories & source detail</h2>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable report tables need keyboard focus.) -->
 <div class="table-scroll" role="region" aria-label="Cost category report" tabindex="0"><table><caption>Budget, committed, actual and forecast by category</caption><thead><tr><th scope="col">Job / trade</th><th scope="col">Category</th><th scope="col">Budget</th><th scope="col">Remaining commitment</th><th scope="col">Actual</th><th scope="col">Remaining forecast</th><th scope="col">EAC</th><th scope="col">Actual / forecast variance</th></tr></thead><tbody>{#each (c.categoryReport??[]).filter(r=>(!selected||r.jobId===selected)&&(!trade||r.trade===trade)) as row}<tr><th scope="row">{jobName(row.jobId)} · {row.trade}</th><td>{row.category}</td><td>{money(row.budget)}</td><td>{money(row.remainingCommitment)}</td><td>{money(row.actual)}</td><td>{money(row.forecastRemaining)}</td><td>{money(row.estimatedFinalCost)}</td><td>{money(row.actualVariance)} / {money(row.forecastVariance)}</td></tr>{:else}<tr><td colspan="8">No category report inputs available.</td></tr>{/each}</tbody></table></div><details><summary>Job cost transaction sources</summary>{#each (c.costDrilldown??[]).filter(r=>!selected||r.jobId===selected) as group}<h3>{jobName(group.jobId)} · {group.category} · {group.costCode||'No cost code'}</h3>{#each group.sources as source}<p>{source.date} · {money(source.amount)} · {source.sourceType} {source.sourceId} · Journal {source.journalId||'No journal'}</p>{/each}{:else}<p>No posted construction cost sources.</p>{/each}</details><details><summary>Authoritative SOV billing balances</summary>{#each (c.scheduleOfValues??[]).filter(r=>!selected||r.jobId===selected) as line}<p>{jobName(line.jobId)} · {line.id} {line.description} · Prior {money(line.priorBilled)} · Current {money(line.currentBilled)} · Total {money(line.totalBilled)} · Complete {percent(line.percentComplete)} · Withheld {money(line.retainageWithheldToDate)} · Balance to finish {money(line.balanceToFinish)}</p>{:else}<p>No SOV billing balances available.</p>{/each}</details></section>
 <section id="billing"><h2>Progress billing</h2><p>Applications preserve prior billing. Review and approve an application before issuing its invoice.</p>
 {#each s.applications.filter(a=>!selected||a.jobId===selected) as app}<article><h3>{app.number} · {jobName(app.jobId)}</h3><p>{app.periodStart} – {app.periodEnd} · Status: <strong>{app.status}</strong></p><dl><div><dt>Prior billed</dt><dd>{money(app.priorBilled)}</dd></div><div><dt>Current billing</dt><dd>{money(app.currentBilling)}</dd></div><div><dt>Retainage withheld</dt><dd>{money(app.retainage)}</dd></div><div><dt>Net due</dt><dd>{money(app.totalDue)}</dd></div></dl><details><summary>Application source lines</summary>{#each app.lines as line}<p>{line.sovLineId} · New completed work {money(line.currentBilling)} · New stored {money(line.newStoredMaterials??0)} · Installed from previously billed stored {money(line.installedFromStored??0)}</p>{/each}<p>Application ID: {app.id}</p>{#if app.invoiceId}<p>AR document: {app.invoiceId} · Journal: {app.journalId}</p>{/if}</details>
 {#if c.canWrite&&app.status==='DRAFT'||c.canControl&&['IN_REVIEW','APPROVED'].includes(app.status)}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={c.version}/><input type="hidden" name="target" value={app.id}/><label>Review / posting evidence<input name="reason" required/></label>{#if app.status==='DRAFT'}<button name="action" value="submit-application">Submit for review</button>{:else if app.status==='IN_REVIEW'}<button name="action" value="approve-application">Approve application</button>{:else}<button class="primary" name="action" value="invoice-application">Issue approved invoice</button>{/if}{#if c.canControl}<button name="action" value="void-application">Void unissued application</button>{/if}</form>{/if}</article>{:else}<p>No pay applications in this view.</p>{/each}
 {#if c.canWrite}<details><summary>Create a pay application</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="application"/><label>Job<select name="jobId" required>{#each s.contracts.filter(j=>j.progressBillingEnabled) as j}<option value={j.jobId}>{jobName(j.jobId)}</option>{/each}</select></label><label>Application number<input name="number" required/></label><label>Period start<input type="date" name="periodStart" required/></label><label>Period end<input type="date" name="periodEnd" required/></label><label class="wide">Billing lines (SOV line ID, new completed work, new stored materials, installed from prior stored — one per row)<textarea name="lines" rows="4" required></textarea></label><label class="wide">Supporting document references (comma separated; required for new stored materials)<input name="documents"/></label><label class="wide">Supporting evidence<input name="reason" required/></label><button class="primary">Save draft application</button></form></details>{/if}
 <details><summary>Schedule of values</summary>{#each s.contracts.filter(j=>!selected||j.jobId===selected) as contract}<h3>{jobName(contract.jobId)}</h3><p>Original {money(contract.originalValue)} + approved changes {money(contract.approvedChanges)} = current contract {money(contract.currentValue)} · Retainage {contract.retainagePercent}%</p><table><caption>{jobName(contract.jobId)} contract schedule</caption><thead><tr><th scope="col">Line</th><th scope="col">Description</th><th scope="col">Original</th><th scope="col">Approved changes</th><th scope="col">Current</th></tr></thead><tbody>{#each contract.lines as line}<tr><th scope="row">{line.id}</th><td>{line.description}</td><td>{money(line.originalValue)}</td><td>{money(line.approvedChanges)}</td><td>{money(line.currentValue)}</td></tr>{/each}</tbody></table>{/each}</details>
 </section>
 <section><h2>Construction payment links</h2><p>{data.payments?.configured?'Tenant connected Stripe account is configured. Dispatch creates a card checkout for the current net AR balance.':'Payment provider is not configured for this tenant. Existing manual receipt workflows remain available.'}</p>{#each data.payments?.intents??[] as intent}<article><h3>{intent.openItemId} · {money(intent.amount)} · {intent.status}</h3>{#if intent.error}<p>{intent.error}</p>{/if}{#if intent.url}<a href={intent.url} rel="noopener noreferrer">Open tenant payment checkout</a>{/if}{#if c.canControl&&['PENDING','READY','CANCEL_PENDING'].includes(intent.status)}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={data.payments?.version}/><input type="hidden" name="target" value={intent.id}/><label>Payment operation evidence<input name="reason" required/></label>{#if intent.status==='PENDING'}<button name="action" value="payment-retry">Retry original checkout intent</button>{/if}<button name="action" value="payment-cancel">Expire checkout before changing AR</button></form>{/if}</article>{/each}{#each data.payments?.receipts??[] as receipt}<p>Provider receipt {receipt.eventId} · {receipt.status} · {receipt.error||'Recorded'}</p>{/each}{#if c.canControl&&data.payments?.configured}<details><summary>Create construction checkout</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={data.payments.version}/><input type="hidden" name="action" value="payment-create"/><label>Issued construction AR<select name="openItemId" required>{#each w.state.openItems.filter(i=>s.applications.some(a=>a.invoiceId===i.id)||s.retainageReleases.some(r=>r.openItemId===i.id)) as item}<option value={item.id}>{item.number} · {money(item.total)}</option>{/each}</select></label><label>Receiving cash / processor clearing account<select name="cashAccountId" required>{#each w.state.cashAccounts as account}<option value={account.id}>{account.name}</option>{/each}</select></label><label>Owner dispatch authorization<input name="reason" required/></label><button>Create net AR card checkout</button></form></details><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={data.payments.version}/><input type="hidden" name="action" value="payment-reconcile"/><label>Reconciliation authorization<input name="reason" required/></label><button>Retry pending verified payment postings</button></form>{/if}</section>
 <section id="retainage"><h2>Retainage receivable</h2>{#each visible as j}<article><h3>{jobName(j.jobId)} · {money(j.retainageHeld)} remaining</h3>{#if c.canControl&&j.retainageHeld>0}<form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="release-retainage"/><input type="hidden" name="jobId" value={j.jobId}/><label>Release date<input type="date" name="date" required/></label><label>Amount to release<input type="number" name="amount" min="0.01" max={j.retainageHeld} step="0.01" required/></label><label class="wide">Milestone / release authorization<input name="reason" required/></label><button class="primary">Release to customer AR</button></form>{/if}</article>{/each}<details><summary>Release audit</summary>{#each s.retainageReleases as release}<p>{jobName(release.jobId)} · {release.date} · {money(release.amount)} · {release.reason} · AR {release.openItemId}</p>{:else}<p>No releases recorded.</p>{/each}</details></section>
 <section id="wip"><h2>WIP & period close</h2><p>Review missing EAC and cost exceptions before approval. Posted snapshots preserve the period calculation.</p>
 {#if c.canWrite}<form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="calculate-wip"/><label>Accounting period<select name="periodId" required>{#each w.state.periods.filter(p=>p.status!=='CLOSED') as p}<option value={p.id}>{p.id} · {p.start} – {p.end}</option>{/each}</select></label><label>Review evidence<input name="reason" required/></label><button>Calculate WIP draft</button></form>{/if}
 {#each s.wipSnapshots as snapshot}<article><h3>{snapshot.periodId} · {snapshot.status}</h3><a href={`${data.basePath}/finance/construction/export?type=wip&snapshot=${snapshot.id}`}>Export {snapshot.periodId} WIP snapshot CSV</a><p>Snapshot {snapshot.id}{snapshot.journalId?` · Posted journal ${snapshot.journalId}`:''}</p>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable financial tables need keyboard focus.) -->
 <div class="table-scroll" role="region" aria-label="WIP snapshot table" tabindex="0"><table><caption>WIP snapshot {snapshot.periodId}</caption><thead><tr><th scope="col">Job</th><th scope="col">Complete</th><th scope="col">Earned revenue</th><th scope="col">Billed</th><th scope="col">Underbilling / contract asset</th><th scope="col">Overbilling / contract liability</th><th scope="col">Exceptions</th></tr></thead><tbody>{#each snapshot.jobs as j}<tr><th scope="row">{jobName(j.jobId)}</th><td>{percent(j.percentComplete)}</td><td>{money(j.earnedRevenue)}</td><td>{money(j.billed)}</td><td>{money(j.underbilling)}</td><td>{money(j.overbilling)}</td><td>{j.exceptions.join('; ')||'None'}</td></tr>{/each}</tbody></table></div>
 {#if c.canControl&&['DRAFT','APPROVED'].includes(snapshot.status)}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={c.version}/><input type="hidden" name="target" value={snapshot.id}/><label>Approval / posting evidence<input name="reason" required/></label><button class="primary" name="action" value={snapshot.status==='DRAFT'?'approve-wip':'post-wip'}>{snapshot.status==='DRAFT'?'Approve WIP snapshot':'Post approved WIP journal'}</button></form>{/if}</article>{:else}<p>No period snapshots calculated.</p>{/each}
 </section>
 <section><h2>Cost-code budget allocation</h2><p>Reviewed allocations must reconcile to known category budgets. Unclassified and stale allocations remain visible exceptions.</p>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable financial reports need keyboard focus.) -->
 <div class="table-scroll" role="region" aria-label="Cost-code report" tabindex="0"><table><caption>Budget, actual, commitment and forecast by cost code</caption><thead><tr><th scope="col">Job / category / code</th><th scope="col">Budget</th><th scope="col">Actual</th><th scope="col">Remaining commitment</th><th scope="col">Forecast remaining</th><th scope="col">EAC</th><th scope="col">Actual / forecast variance</th><th scope="col">Allocation evidence</th></tr></thead><tbody>{#each (c.codeReport??[]).filter(r=>!selected||r.jobId===selected) as row}<tr><th scope="row">{jobName(row.jobId)} · {row.category} · {row.costCode||'Unclassified'}</th><td>{money(row.budget)}</td><td>{money(row.actual)}</td><td>{money(row.remainingCommitment)}</td><td>{money(row.forecastRemaining)}</td><td>{money(row.estimatedFinalCost)}</td><td>{money(row.actualVariance)} / {money(row.forecastVariance)}</td><td>{row.unclassified?'Unclassified · ':''}{row.allocationCurrent?'Current allocation':'Allocation requires review'} · {row.allocationNote}<details><summary>Cost-code sources</summary>{#each row.sources as source}<p>{source.kind} · {source.sourceId} · {money(source.amount)} · Journal {source.journalId||'None'}</p>{/each}</details></td></tr>{:else}<tr><td colspan="8">No cost-code report inputs.</td></tr>{/each}</tbody></table></div>{#if c.canWrite}<details><summary>Draft cost-code budget allocation</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="draft-code-budget"/><label>Job<select name="jobId">{#each s.contracts as contract}<option value={contract.jobId}>{jobName(contract.jobId)}</option>{/each}</select></label><label>Allocation date<input name="date" type="date" required/></label><label class="wide">Allocation rows (category, cost code, budget amount)<textarea name="lines" rows="4" required></textarea></label><label>Allocation source evidence<input name="reason" required/></label><button>Save allocation draft</button></form></details>{/if}{#if c.canControl}<details><summary>Code a remaining commitment</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="code-commitment"/><label>Job<select name="jobId">{#each s.contracts as contract}<option value={contract.jobId}>{jobName(contract.jobId)}</option>{/each}</select></label><label>Approved order<select name="orderId"><option value="">Standalone imported commitment</option>{#each w.orders as order}<option value={order.id}>{order.number}</option>{/each}</select></label><label>Order line ID<input name="orderLineId"/></label><label>Imported commitment source ID<input name="importedCommitmentId"/></label><label>Cost code<select name="costCode">{#each w.state.costCodes as code}<option value={code.code}>{code.code} · {code.name}</option>{/each}</select></label><label>Coding date<input name="date" type="date" required/></label><label>Source coding evidence<input name="reason" required/></label><button>Record reviewed commitment coding</button></form></details>{/if}{#each s.codeBudgets??[] as revision}<article><h3>{jobName(revision.jobId)} · {revision.date} · {revision.status}</h3><p>{revision.reason}</p>{#each revision.lines as line}<p>{line.category} / {line.costCode} · {money(line.amount)}</p>{/each}{#if c.canControl&&revision.status==='DRAFT'}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={c.version}/><input type="hidden" name="target" value={revision.id}/><input type="hidden" name="action" value="review-code-budget"/><label>Allocation review evidence<input name="reason" required/></label><button>Review reconciled allocation</button></form>{/if}</article>{/each}</section>
 <section id="setup"><h2>Setup & forecasts</h2>{#if c.canControl}
 <details><summary>Map construction GL accounts</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="policy"/>{#each ['retainage','contractAsset','contractLiability','billing'] as role}<label>{role}<select name={`map.${role}`} required><option value="">Choose active account</option>{#each w.state.accounts.filter(a=>a.active) as account}<option value={account.code} selected={s.accounts[role]===account.code}>{account.code} · {account.name}</option>{/each}</select></label>{/each}<label>Mapping reason<input name="reason" required/></label><button>Save reviewed mappings</button></form></details>
 <details><summary>Configure contract and schedule of values</summary><p>Contract totals must match the accepted Job and approved changes. SOV lines must reconcile to those totals.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="contract"/><label>Job<select name="jobId" required>{#each w.jobChoices as j}<option value={j.id}>{j.name}</option>{/each}</select></label><label>Customer ID<input name="customerId" required/></label><label>Original contract value<input name="originalValue" type="number" min="0" step="0.01" required/></label><label>Approved changes<input name="approvedChanges" type="number" step="0.01" value="0" required/></label><label>Retainage percent<input name="retainagePercent" type="number" min="0" max="100" step="0.01" value="10" required/></label><label>Revenue recognition<select name="recognitionMethod"><option value="COST_TO_COST">Cost-to-cost</option><option value="COMPLETED_CONTRACT">Completed contract</option></select></label><label><span><input name="progressBillingEnabled" type="checkbox" checked/>Enable progress billing</span></label><label><span><input name="completed" type="checkbox"/>Contract completed</span></label><label class="wide">SOV lines (ID, description, original amount, approved changes, cost code)<textarea name="lines" rows="4" required></textarea></label><label class="wide">Contract evidence<input name="reason" required/></label><button>Save contract and SOV</button></form></details>{/if}
 {#if c.canControl}<details><summary>Record reviewed forecast to complete</summary><p>Remaining forecast must cover the remaining scope and commitments. A reviewed forecast is required to calculate EAC.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={c.version}/><input type="hidden" name="action" value="forecast"/><label>Job<select name="jobId" required>{#each s.contracts as j}<option value={j.jobId}>{jobName(j.jobId)}</option>{/each}</select></label><label>Forecast date<input type="date" name="date" required/></label><label>Remaining forecast<input name="remainingForecast" type="number" min="0" step="0.01" required/></label><label class="wide">Category forecast rows (category, cost code, remaining amount)<textarea name="forecastCosts" rows="3"></textarea></label><label class="wide">Evidence and assumptions<input name="reason" required/></label><label class="wide"><span><input name="complete" type="checkbox"/>I reviewed all remaining scope and confirm the forecast is complete.</span></label><button>Record forecast revision</button></form></details>{/if}<details><summary>Forecast revision evidence</summary>{#each s.forecasts as forecast}<p>{jobName(forecast.jobId)} · {forecast.date} · {money(forecast.remainingForecast)} · {forecast.complete?'Reviewed complete':'Incomplete'} · {forecast.reason}</p>{:else}<p>No forecast revisions.</p>{/each}</details>
 </section>
</div>
<style>
 .construction{--ink:var(--text-primary,#183039);--surface:var(--bg-card,#fff);--line:var(--border-color,#b9c8ca);color:var(--ink);max-width:100%;padding:1.5rem;display:grid;gap:1.25rem}header,.heading,nav{display:flex;gap:1rem;align-items:center;justify-content:space-between;flex-wrap:wrap}h1{font-size:1.8rem}h2{font-size:1.3rem}h3{font-size:1.05rem}h1,h2,h3{font-weight:650;margin:.3rem 0 .7rem}p{margin:.5rem 0;line-height:1.6}.eyebrow{font-size:.75rem;letter-spacing:.12em;color:#147b79}section{background:var(--surface);border:1px solid var(--line);border-radius:.75rem;padding:1.25rem;min-width:0;scroll-margin-top:1rem}article{padding:1rem 0;border-top:1px solid var(--line)}a{text-decoration:underline;text-underline-offset:3px}nav{justify-content:flex-start}nav a{padding:.5rem}.editor{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:1rem 0}label{display:flex;flex-direction:column;gap:.35rem;font-weight:550}input,select,textarea{border:1px solid var(--line);border-radius:.35rem;padding:.6rem;background:var(--surface);color:inherit;min-width:0;max-width:100%}input[type=checkbox]{width:1rem;height:1rem}button{border:1px solid var(--line);border-radius:.4rem;padding:.6rem .85rem;min-height:44px;background:var(--surface);color:inherit;cursor:pointer;align-self:end}.primary{background:#a94b0b;color:white;border-color:#a94b0b}:is(button,a,input,select,textarea,summary):focus-visible{outline:3px solid #16817c;outline-offset:3px}.wide{grid-column:1/-1}details{margin:1rem 0}summary{cursor:pointer;padding:.5rem 0;font-weight:600}dl{display:flex;flex-wrap:wrap;gap:1.5rem}dt{font-size:.85rem}dd{font-weight:650;margin:0}.table-scroll{overflow:auto;max-width:100%}table{width:100%;border-collapse:collapse;text-align:left;font-size:.9rem}th,td{padding:.7rem;border-bottom:1px solid var(--line);vertical-align:top}caption{text-align:left;padding:.75rem 0;font-weight:600}.feedback{padding:1rem;border:1px solid var(--line);border-left:4px solid #147b79} :global([data-theme=dark]) .construction{--ink:#e0ebed;--surface:#132b34;--line:#56717a} :global([data-theme=dark]) .eyebrow{color:#7cdbd4}@media(max-width:600px){.construction{padding:.75rem}section{padding:.8rem}.editor{grid-template-columns:1fr}}@media print{nav,form,button,header>a{display:none}details{display:block}section{break-inside:avoid}.table-scroll{overflow:visible}table{font-size:8pt}}
